  const c2 = card('② 계약 조건', '<div class="jh-hr__pad"><div>' + rad('empKind', 'regular', '정규직') + rad('empKind', 'contract', '계약직') + '</div>' + two(dt('startDate', '적용 시작일'), dt('endDate', '적용 종료일')) + two(txt('hoursDay', '1일 소정근로 (시간)'), txt('hoursWeek', '주 소정근로 (시간)')) + txt('probation', '수습 기간 (개월 · 없으면 비움)') + '</div>');
