export function offerHistHtml(st) {
  const tab = st.histTab; const offers = st.allOffers;
  const tabs = '<div class="jh-segmented" role="group" aria-label="구분"><button type="button" class="jh-segmented__item" data-o-tab="active" aria-pressed="' + (tab === 'active') + '">🟢 재직자</button><button type="button" class="jh-segmented__item" data-o-tab="pending" aria-pressed="' + (tab === 'pending') + '">🆕 신규입사 예정자</button></div>';
  let body;
  if (tab === 'active') {
    const act = st.allWorkers.filter((w) => w.status !== 'resigned').sort((a, b) => String(a.empNo || '').localeCompare(String(b.empNo || '')));
    body = act.length ? '<div class="jh-hr__scroll"><table class="jh-hr-table jh-hr-table--click"><thead><tr><th>사원번호</th><th>이름</th><th>소속</th><th>직급</th><th>제안서</th></tr></thead><tbody>' + act.map((w) => { const n = offers.filter((o) => o.workerId === w.id).length; return '<tr class="jh-hr__row" data-o-person="w|' + esc(w.id) + '"><td>' + esc(w.empNo || '-') + '</td><td><strong>' + esc(w.name || '-') + '</strong></td><td>' + esc(w.dept || '-') + '</td><td>' + esc(w.rank || '-') + '</td><td>' + (n ? n + '건' : '-') + '</td></tr>'; }).join('') + '</tbody></table></div><div class="jh-field__hint jh-hr__pad">이름을 누르면 해당 근로자의 재계약/연봉조정 제안서 이력을 봅니다.</div>' : '<div class="jh-empty">등록된 근로자가 없습니다.</div>';
  } else {
    const by = {}; offers.forEach((o) => { if (o.applicantId) (by[o.applicantId] = by[o.applicantId] || []).push(o); });
    const el = st.allApplicants.filter((a) => by[a.id] && ['review', 'pass'].includes(a.status || 'new'));
    body = el.length ? '<div class="jh-hr__scroll"><table class="jh-hr-table jh-hr-table--click"><thead><tr><th>이름</th><th>지원 공고</th><th>상태</th><th>제안서</th></tr></thead><tbody>' + el.map((a) => '<tr class="jh-hr__row" data-o-person="a|' + esc(a.id) + '"><td><strong>' + esc(a.name || '-') + '</strong></td><td>' + (a.jobTitle ? chip(a.jobTitle, 'accent') : '-') + '</td><td>' + chip(a.status === 'pass' ? '합격' : '검토중', a.status === 'pass' ? 'accent' : 'warn') + '</td><td>' + by[a.id].length + '건</td></tr>').join('') + '</tbody></table></div><div class="jh-field__hint jh-hr__pad">지원자가 \'불합격\'·\'신규\'로 바뀌면 이 목록에서 자동으로 빠집니다.</div>' : '<div class="jh-empty">제안서가 작성된 신규입사 예정자가 없습니다.<br><span class="jh-field__hint">채용 지원자 중 \'검토중\' 또는 \'합격\' 상태이면서 연봉 제안서를 한 번이라도 저장한 경우에만 표시됩니다.</span></div>';
  }
  return card('📜 지난 제안서', '<div class="jh-hr__pad"><div class="jh-hr__bar"><button type="button" class="jh-btn" data-variant="ghost" data-o-act="form">← 제안서 작성</button>' + tabs + '</div></div>' + body);
}
export function offerPersonHtml(st) {
  const p = st.person; const fmt = (ts) => { const d = ts && ts.toDate ? ts.toDate() : ts ? new Date(ts) : null; return d && !Number.isNaN(d.getTime()) ? d.getFullYear() + '.' + String(d.getMonth() + 1).padStart(2, '0') + '.' + String(d.getDate()).padStart(2, '0') + ' ' + String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0') : '-'; };
  const list = p.list.length ? p.list.map((o) => { const r = offerCalc(o); return '<div class="jh-hr__post"><div class="jh-hr__bar"><strong>' + esc(OFFER_KIND[o.kind] || o.kind) + ' · ' + esc(o.offerDate || '-') + '</strong>' + chip(fmt(o.createdAt) + ' 작성', 'accent') + '</div><div class="jh-field__hint">제안 연봉: ' + (r.ok ? ow(r.annual) : '-') + '</div><div class="jh-hr__bar"><button type="button" class="jh-btn" data-variant="secondary" data-o-reprint="' + esc(o.id) + '">🖨 다시 출력</button><button type="button" class="jh-btn" data-variant="ghost" data-o-edit="' + esc(o.id) + '">✏️ 열어서 수정</button><button type="button" class="jh-btn" data-variant="ghost" data-o-del="' + esc(o.id) + '">🗑 삭제</button></div></div>'; }).join('') : '<div class="jh-empty">작성된 제안서가 없습니다.</div>';
  return card(esc(p.name) + ' · 연봉 제안서 이력', '<div class="jh-hr__pad"><div class="jh-hr__bar"><button type="button" class="jh-btn" data-variant="ghost" data-o-act="histback">← 목록</button><button type="button" class="jh-btn" data-variant="primary" data-o-act="newfor">➕ 새 제안서 작성</button></div></div><div class="jh-hr__pad">' + list + '</div>');
}
export function offersHtml(st) { return st.view === 'hist' ? offerHistHtml(st) : st.view === 'person' ? offerPersonHtml(st) : offerFormHtml(st); }
